hevron-down']\" />\n          <span class=\"draft-name flex-1 truncate\">{{ draft.name || 'Untitled' }}</span>\n          <button class=\"del-btn\" title=\"删除\" @click.stop=\"store.removeDraft(draft.id)\">\n            <i class=\"fas fa-times text-xs\" />\n          </button>\n        </div>\n\n        <div v-if=\"!draft.collapsed\" class=\"draft-body\">\n          <input\n            class=\"draft-input\"\n            placeholder=\"条目名称\"\n            :value=\"draft.name\"\n            @input=\"store.updateDraft(draft.id, { name: ($event.target as HTMLInputElement).value })\"\n          />\n          <select\n            class=\"draft-select\"\n            :value=\"draft.role\"\n            @change=\"store.updateDraft(draft.id, { role: ($event.target as HTMLSelectElement).value as any })\"\n          >\n            <option value=\"system\">system</option>\n            <option value=\"user\">user</option>\n            <option value=\"assistant\">assistant</option>\n          </select>\n          <textarea\n            class=\"draft-textarea\"\n            placeholder=\"提示词内容...\"\n            :value=\"draft.content\"\n            rows=\"4\"\n            @input=\"store.updateDraft(draft.id, { content: ($event.target as HTMLTextAreaElement).value })\"\n          />\n        </div>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useManagerStore, type DraftPrompt } from '../stores/manager';\n\nconst store = useManagerStore();\n\nconst drafts = computed(() => store.drafts);\n\nfunction toggleDraft(draft: DraftPrompt) {\n  store.updateDraft(draft.id, { collapsed: !draft.collapsed });\n}\n\nfunction onDragStart(e: DragEvent, draft: DraftPrompt) {\n  const prompt = store.draftToPrompt(draft);\n  e.dataTransfer!.effectAllowed = 'copy';\n  e.dataTransfer!.setData(\n    'application/json',\n    JSON.stringify({\n      type: 'draft',\n      source: 'workbench',\n      prompt,\n    }),\n  );\n}\n</script>\n\n<style scoped>\n.panel-title {\n  border-bottom: 1px solid rgba(51, 65, 85, 0.3);\n  padding-right: 40px;\n}\n.add-btn {\n  width: 24px;\n  height: 24px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  border-radius: 5px;\n  border: 1px solid rgba(51, 65, 85, 0.5);\n  background: transparent;\n  color: #94a3b8;\n  cursor: pointer;\n  transition: all 0.12s;\n}\n.add-btn:hover {\n  background: rgba(99, 102, 241, 0.15);\n  color: #818cf8;\n  border-color: rgba(99, 102, 241, 0.4);\n}\n.draft-item {\n  border: 1px solid rgba(51, 65, 85, 0.3);\n  border-radius: 6px;\n  background: rgba(15, 23, 42, 0.5);\n  margin-bottom: 4px;\n  cursor: grab;\n}\n.draft-item:hover {\n  border-color: rgba(99, 102, 241, 0.3);\n}\n.draft-header {\n  display: flex;\n  align-items: center;\n  padding: 6px 8px;\n  cursor: pointer;\n}\n.draft-name {\n  font-size: 12px;\n  color: #cbd5e1;\n}\n.del-btn {\n  width: 20px;\n  height: 20px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  border-radius: 4px;\n  border: none;\n  background: transparent;\n  color: #64748b;\n  cursor: pointer;\n}\n.del-btn:hover {\n  color: #f87171;\n  background: rgba(248, 113, 113, 0.1);\n}\n.draft-body {\n  padding: 6px 8px 8px;\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n  border-top: 1px solid rgba(51, 65, 85, 0.2);\n}\n.draft-input,\n.draft-select {\n  width: 100%;\n  padding: 4px 8px;\n  border-radius: 5px;\n  border: 1px solid rgba(51, 65, 85, 0.4);\n  background: rgba(0, 0, 0, 0.2);\n  color: #e2e8f0;\n  font-size: 12px;\n  outline: none;\n}\n.draft-input:focus,\n.draft-select:focus {\n  border-color: rgba(99, 102, 241, 0.5);\n}\n.draft-select option {\n  background: #1e293b;\n}\n.draft-textarea {\n  width: 100%;\n  padding: 6px 8px;\n  border-radius: 5px;\n  border: 1px solid rgba(51, 65, 85, 0.4);\n  background: rgba(0, 0, 0, 0.2);\n  color: #e2e8f0;\n  font-size: 12px;\n  resize: vertical;\n  min-height: 60px;\n  outline: none;\n  font-family: inherit;\n}\n.draft-textarea:focus {\n  border-color: rgba(99, 102, 241, 0.5);\n}\n</style>\n"],"sourceRoot":""}]);
