                <i class=\"fas fa-copy text-xs\" />\n                <Transition name=\"fade\">\n                  <span v-if=\"copied\" class=\"copy-toast\">已复制</span>\n                </Transition>\n              </button>\n              <button class=\"overlay-btn hover:!text-red-400\" title=\"关闭\" @click=\"$emit('close')\">\n                <i class=\"fas fa-times text-xs\" />\n              </button>\n            </div>\n          </div>\n\n          <div class=\"overlay-body\">\n            <pre class=\"overlay-content\">{{ prompt.content ?? '[无内容]' }}</pre>\n          </div>\n\n          <div v-if=\"showActions\" class=\"overlay-footer\">\n            <button class=\"footer-btn\" @click=\"$emit('edit')\">\n              <i class=\"fas fa-edit text-xs\" /> 编辑\n            </button>\n            <button class=\"footer-btn\" @click=\"$emit('toggleFavorite')\">\n              <i :class=\"['text-xs', isFavorited ? 'fas fa-star text-amber-400' : 'far fa-star']\" />\n              {{ isFavorited ? '取消收藏' : '收藏' }}\n            </button>\n          </div>\n        </div>\n      </div>\n    </Transition>\n  </Teleport>\n</template>\n\n<script setup lang=\"ts\">\nconst props = defineProps<{\n  visible: boolean;\n  prompt: PresetPrompt;\n  isFavorited?: boolean;\n  showActions?: boolean;\n}>();\n\ndefineEmits<{\n  close: [];\n  edit: [];\n  toggleFavorite: [];\n}>();\n\nconst copied = ref(false);\nlet copyTimer: ReturnType<typeof setTimeout>;\n\nasync function copyContent() {\n  const text = props.prompt?.content ?? '';\n  try {\n    await navigator.clipboard.writeText(text);\n  } catch {\n    const textarea = document.createElement('textarea');\n    textarea.value = text;\n    document.body.appendChild(textarea);\n    textarea.select();\n    document.execCommand('copy');\n    document.body.removeChild(textarea);\n  }\n  copied.value = true;\n  clearTimeout(copyTimer);\n  copyTimer = setTimeout(() => (copied.value = false), 1500);\n}\n</script>\n\n<style scoped>\n.overlay-backdrop {\n  position: fixed;\n  inset: 0;\n  background: rgba(0, 0, 0, 0.5);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  z-index: 1000;\n  backdrop-filter: blur(2px);\n}\n.overlay-card {\n  width: 90%;\n  max-width: 700px;\n  max-height: 80%;\n  background: rgba(15, 23, 42, 0.95);\n  border: 1px solid rgba(51, 65, 85, 0.6);\n  border-radius: 12px;\n  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.5);\n  display: flex;\n  flex-direction: column;\n  overflow: hidden;\n}\n.overlay-header {\n  display: flex;\n  align-items: center;\n  padding: 12px 16px;\n  border-bottom: 1px solid rgba(51, 65, 85, 0.4);\n  gap: 8px;\n}\n.overlay-title {\n  font-size: 15px;\n  font-weight: 600;\n  color: #e2e8f0;\n  word-break: break-all;\n}\n.role-badge {\n  font-size: 10px;\n  padding: 2px 8px;\n  border-radius: 4px;\n  font-weight: 500;\n  text-transform: uppercase;\n  flex-shrink: 0;\n}\n.role-badge.system { background: rgba(99, 102, 241, 0.15); color: #818cf8; }\n.role-badge.user { background: rgba(34, 197, 94, 0.15); color: #4ade80; }\n.role-badge.assistant { background: rgba(251, 146, 60, 0.15); color: #fb923c; }\n.overlay-btn {\n  position: relative;\n  width: 32px;\n  height: 32px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  border-radius: 6px;\n  border: none;\n  background: transparent;\n  color: #94a3b8;\n  cursor: pointer;\n  transition: all 0.12s;\n}\n.overlay-btn:hover { background: rgba(51, 65, 85, 0.6); color: #e2e8f0; }\n.copy-toast {\n  position: absolute;\n  top: -24px;\n  left: 50%;\n  transform: translateX(-50%);\n  padding: 2px 8px;\n  background: #4ade80;\n  color: #0f172a;\n  font-size: 10px;\n  border-radius: 4px;\n  white-space: nowrap;\n  pointer-events: none;\n}\n.overlay-body {\n  flex: 1;\n  overflow-y: auto;\n  padding: 16px;\n}\n.overlay-content {\n  font-size: 13px;\n  line-height: 1.6;\n  color: #cbd5e1;\n  white-space: pre-wrap;\n  word-break: break-all;\n  margin: 0;\n  font-family: inherit;\n}\n.overlay-footer {\n  display: flex;\n  gap: 8px;\n  padding: 12px 16px;\n  border-top: 1px solid rgba(51, 65, 85, 0.4);\n}\n.footer-btn {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  padding: 6px 12px;\n  border-radius: 6px;\n  border: 1px solid rgba(51, 65, 85, 0.4);\n  background: rgba(30, 41, 59, 0.6);\n  color: #94a3b8;\n  font-size: 12px;\n  cursor: pointer;\n  transition: all 0.12s;\n}\n.footer-btn:hover { background: rgba(51, 65, 85, 0.6); color: #e2e8f0; border-color: rgba(99, 102, 241, 0.4); }\n.overlay-enter-active, .overlay-leave-active { transition: opacity 0.15s; }\n.overlay-enter-from, .overlay-leave-to { opacity: 0; }\n.fade-enter-active, .fade-leave-active { transition: opacity 0.15s; }\n.fade-enter-from, .fade-leave-to { opacity: 0; }\n</style>\n"],"sourceRoot":""}]);
